R = []
def add(id, cat, what, why, owner, src, bv, so, gap, conf, eff, risk, bucket, deps=""):
    R.append({
        "id": id, "category": cat, "what": what, "why": why, "owner": owner,
        "source": src, "business_value": bv, "search_opportunity": so,
        "current_performance_gap": gap, "confidence": conf, "effort": eff,
        "risk": risk, "bucket": bucket, "dependencies": deps,
    })

